import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":1786971590000}'),s={name:"zh/guide/architecture.md"};function l(r,a,o,p,d,c){return n(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>NeoFlux 采用两层架构，层间通过无锁环形队列通信。</p><h2 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to &quot;架构图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---------------------------+         +---------------------------+</span></span>
<span class="line"><span>|   Application Layer       |  SPSC   |   Render Layer            |</span></span>
<span class="line"><span>|   (UI 线程)               |  Ring   |   (渲染线程)              |</span></span>
<span class="line"><span>|                           |  Queue  |                           |</span></span>
<span class="line"><span>|  - Widget Tree            | +-----&gt; |  - tgfx Renderer          |</span></span>
<span class="line"><span>|  - Taitank Layout Engine  |         |  - GLFW Bridge (桌面端)  |</span></span>
<span class="line"><span>|  - Event Loop             |         |  - Command Execution      |</span></span>
<span class="line"><span>|  - Route Navigation       |         |                           |</span></span>
<span class="line"><span>+---------------------------+         +---------------------------+</span></span></code></pre></div><h2 id="application-层" tabindex="-1">Application 层 <a class="header-anchor" href="#application-层" aria-label="Permalink to &quot;Application 层&quot;">​</a></h2><p>运行业务逻辑，构建 Widget 树，通过 Taitank flexbox 引擎计算布局，记录渲染命令到 RenderContext。</p><p>核心组件：</p><ul><li><strong>Application</strong>：框架入口，管理窗口、事件循环、路由栈</li><li><strong>EventLoop</strong>：CV 驱动的帧调度，协程调度器，定时器队列</li><li><strong>RouteRegistry</strong>：路由注册表，支持路由注册与导航栈</li><li><strong>Widget Tree</strong>：Widget 组成的 UI 树，Taitank 节点绑定</li></ul><h2 id="render-层" tabindex="-1">Render 层 <a class="header-anchor" href="#render-层" aria-label="Permalink to &quot;Render 层&quot;">​</a></h2><p>从 SPSC 环形队列消费命令，使用 tgfx 执行绘制。</p><ul><li><strong>桌面端</strong>：通过 GLFW 创建窗口与 OpenGL 上下文，tgfx 渲染到 GL framebuffer</li><li><strong>移动端</strong>：tgfx 直接渲染到平台提供的 Surface（ANativeWindow / CAMetalLayer）</li></ul><h2 id="spsc-环形队列" tabindex="-1">SPSC 环形队列 <a class="header-anchor" href="#spsc-环形队列" aria-label="Permalink to &quot;SPSC 环形队列&quot;">​</a></h2><p>无锁单生产者单消费者有界环形缓冲区：</p><ul><li>容量运行时可配置（<code>--render_queue_capacity</code>），自动向上取整为 2 的幂</li><li>位运算回绕，缓存行对齐 head/tail，无需互斥锁</li><li>Application 层生产 RenderCommand，Render 层消费执行</li></ul><h2 id="线程模型" tabindex="-1">线程模型 <a class="header-anchor" href="#线程模型" aria-label="Permalink to &quot;线程模型&quot;">​</a></h2><ul><li><strong>UI 线程</strong>：事件处理、布局计算、命令录制</li><li><strong>渲染线程</strong>：命令消费、tgfx 绘制、缓冲区交换</li><li>两层通过 SPSC 队列解耦，无锁竞争</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./widgets">Widget 系统</a></li><li><a href="./rendering">渲染管线</a></li><li><a href="./cross-platform">跨平台</a></li></ul>`,18)])])}const g=e(s,[["render",l]]);export{u as __pageData,g as default};
